import{b as a,O as e,g as o,j as r}from"./chunks/framework.DSt9LnBW.js";const u=JSON.parse('{"title":"如何确认 BUG 是前端、后端、数据库还是环境的锅？","description":"测出问题不难，难的是第一句话该怎么说。很多人一看到页面不对，就本能甩锅：「前端写坏了」「接口有问题」「是不是库里数据脏了」「换个环境再试」。四种说法都能成立，也可能全错——真正浪费时间的，不是修 bug，而是在错误的层上修。这篇文章讲的是一套可复用的定位习惯：先固定现象，再顺着请求链路往下拆，用证据把问题钉在前端、后端、数据库或环境其中一层（有时是两层交界）。不需要你会写整套系统，会看浏览器 Network、会读接口返回、会问对问题就够用。","frontmatter":{"date":"2026-11-02T00:00:00.000Z","tags":["测试","缺陷定位","排查","前后端"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/testing/bug-layer-localization/index.md","filePath":"个人博客/测试/16.如何确认BUG是前端、后端、数据库还是环境的锅？.md","lastUpdated":1793612959000}'),l={name:"blog/testing/bug-layer-localization/index.md"};function d(i,t,s,n,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r("",95)])])}const b=a(l,[["render",d]]);export{u as __pageData,b as default};
